});

test('validatePaymentDetails accepts valid 16-digit card with correct expiry and 3-digit CVV', () => {
  const payment = { cardNumber: '1234567890123456', expiryDate: '12/25', cvv: '123', amount: 10.86 };
  expect(validatePaymentDetails(payment)).toBe(true);
});

test('validatePaymentDetails rejects card with invalid length', () => {
  const cases = ['123456789012345', '12345678901234567'];
  cases.forEach(cardNumber => {
    expect(validatePaymentDetails({...payment, cardNumber})).toBe(false);
  });
});

test('validatePaymentDetails validates CVV is 3 or 4 digits', () => {
  expect(validatePaymentDetails({...payment, cvv: '1234'})).toBe(true);
  expect(validatePaymentDetails({...payment, cvv: '12'})).toBe(false);
});

test('validatePaymentDetails validates expiry date format MM/YY', () => {
  const invalidFormats = ['12-25', '1225', '13/25', '00/25'];
  invalidFormats.forEach(expiryDate => {
    expect(validatePaymentDetails({...payment, expiryDate})).toBe(false);
  });
});

test('validatePaymentDetails rejects expired cards', () => {
  const expiredDate = new Date();
  expiredDate.setMonth(expiredDate.getMonth() - 1);
  const expiryDate = `${String(expiredDate.getMonth() + 1).padStart(2, '0')}/${String(expiredDate.getFullYear()).slice(-2)}`;
  expect(validatePaymentDetails({...payment, expiryDate})).toBe(false);
});

test('calculateSubscriptionPrice returns correct premium tier price with tax and fees', () => {
