  const expected = basePrice * (1 + 0.08 + 0.029);
  expect(calculateSubscriptionPrice('premium')).toBeCloseTo(expected, 2);
});

test('calculateSubscriptionPrice returns correct enterprise tier price', () => {
  const basePrice = 49.99;
  const expected = basePrice * (1 + 0.08 + 0.029);
  expect(calculateSubscriptionPrice('enterprise')).toBeCloseTo(expected, 2);
